  test('TFFU-058: keyboard navigation: links can receive focus and activate with Enter', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, context }) => {
        const links = [{"text":"A/B Testing","url":"http://localhost:7080/abtest","rawHref":"/abtest","category":"navigation","linkType":"internal","containerLabel":"Available Examples","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":false},{"text":"Add/Remove Elements","url":"http://localhost:7080/add_remove_elements/","rawHref":"/add_remove_elements/","category":"navigation","linkType":"internal","containerLabel":"Available Examples","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":false},{"text":"Basic Auth","url":"http://localhost:7080/basic_auth","rawHref":"/basic_auth","category":"navigation","linkType":"internal","containerLabel":"Available Examples","expectedStatus":null,"isVisible":true,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":false}];
        const revisitLinksPage = async () => {
            await tfGoto(page, '/');
            await page.waitForLoadState('domcontentloaded');
        };

        await revisitLinksPage();
        for (const link of links) {
            const locator = link.text
                ? page.getByRole('link', { name: link.text, exact: true }).first()
                : link.rawHref
                    ? page.locator('a[href="' + link.rawHref.replace(/"/g, '\"') + '"]:visible, a[href="' + link.rawHref.replace(/"/g, '\"') + '"]:has(:visible)').first()
                    : page.locator('a[href="' + link.url.replace(/"/g, '\"') + '"]:visible, a[href="' + link.url.replace(/"/g, '\"') + '"]:has(:visible)').first();
            await locator.focus();
            await expect(locator).toBeFocused();
            const urlBeforeInteraction = page.url();

            if (link.targetBehavior === 'new-tab') {
                const popupPromise = context.waitForEvent('page');
                await page.keyboard.press('Enter');
                const popup = await popupPromise;
                await popup.waitForLoadState('domcontentloaded').catch(() => {});
                // Same host and path; a site that upgrades http to https (the-internet's
                // Elemental Selenium link, a 301) has still opened the right page.
                expect(popup.url().replace(/^https?:\/\//, '')).toContain(link.url.replace(/[#?].*$/, '').replace(/^https?:\/\//, ''));
                await popup.close().catch(() => {});
            } else {
                await page.keyboard.press('Enter');
                // Enter only starts the navigation: waiting for the old page's
                // load state returned at once, the URL looked unchanged, and the
                // next link was then looked for on the new site (TFP-123).
                await page.waitForURL((url) => url.href !== urlBeforeInteraction, { timeout: 5000 }).catch(() => {});

                if (page.url() !== urlBeforeInteraction) {
                    // Straight back to the links page: after a cross-site
                    // redirect, goBack() can land on a hop in between.
                    await revisitLinksPage();
                }
            }
        }
    });

  test('TFFU-060: HTTPS/SSL: secure links remain on HTTPS when marked as secure', { annotation: { type: 'gate', description: 'read-only' } }, async ({ request }) => {
        const links = [{"text":"","url":"https://github.com/saucelabs/the-internet","rawHref":"https://github.com/saucelabs/the-internet","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":false,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Sauce Labs","url":"https://saucelabs.com/","rawHref":"https://saucelabs.com/","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];
        // TFP-142: each distinct URL is requested once, for up to 5 s, and
        // the check stops after 20 s. Requesting every link in turn at 15 s
        // each - 59 on one rizonetech.com page, many repeated - ran past the
        // 30 s test timeout on 3 of 5 pages. A URL that can't be reached is
        // named as not checked (link health judges reachability), and the
        // ones left when the budget ends are named too.
        const deadline = Date.now() + 20000;
        const checked = new Set<string>();
        const notChecked: string[] = [];
        const urls = links.filter((link) => !link.rawHref.toLowerCase().startsWith('mailto:')).map((link) => link.url);

        for (const link of links) {
            expect(link.url.startsWith('https://') || link.rawHref.toLowerCase().startsWith('mailto:'), link.url + ' is marked secure but is not https').toBeTruthy();
        }
        for (const url of urls) {
            if (checked.has(url)) continue;
            if (Date.now() > deadline) {
                const left = [...new Set(urls)].filter((other) => !checked.has(other));
                test.info().annotations.push({ type: 'finding', description: left.length + ' secure links not checked: the check stops after 20 s (' + left.slice(0, 5).join(', ') + (left.length > 5 ? ', ...' : '') + ')' });
                break;
            }
            checked.add(url);
            const response = await request.get(url, { failOnStatusCode: false, timeout: 5000 }).catch((error: Error) => error);
            if (response instanceof Error) {
                notChecked.push(url + ' (' + (/timeout/i.test(response.message) ? 'no answer within 5 s' : response.message.split('\n')[0].replace(/^[\w.]+: /, '')) + ')');
                continue;
            }
            expect(response.url().startsWith('https://'), url + ' ended on ' + response.url() + ', not https').toBeTruthy();
        }
        if (notChecked.length > 0) {
            test.info().annotations.push({ type: 'finding', description: 'secure links that could not be reached, so their HTTPS was not checked: ' + notChecked.join(', ') });
        }
    });

  test('TFFU-061: orphan page approximation: each scanned page is linked from another scanned page', { annotation: { type: 'gate', description: 'read-only' } }, async () => {
        // Each page and each of its links by page: origin, path and hash route (#/contact), without an in-page anchor (TFP-166).
        const pages = [{"path":"/","key":"http://localhost:7080/","links":["https://github.com/saucelabs/the-internet","http://localhost:7080/abtest","http://localhost:7080/add_remove_elements","http://localhost:7080/basic_auth","http://localhost:7080/broken_images","http://localhost:7080/canvas","http://localhost:7080/challenging_dom","http://localhost:7080/checkboxes","http://localhost:7080/context_menu","http://localhost:7080/digest_auth","http://localhost:7080/disappearing_elements","http://localhost:7080/drag_and_drop","http://localhost:7080/dropdown","http://localhost:7080/dynamic_content","http://localhost:7080/dynamic_controls","http://localhost:7080/dynamic_loading","http://localhost:7080/entry_ad","http://localhost:7080/exit_intent","http://localhost:7080/download","http://localhost:7080/upload","http://localhost:7080/floating_menu","http://localhost:7080/forgot_password","http://localhost:7080/login","http://localhost:7080/frames","http://localhost:7080/geolocation","http://localhost:7080/horizontal_slider","http://localhost:7080/hovers","http://localhost:7080/infinite_scroll","http://localhost:7080/inputs","http://localhost:7080/jqueryui/menu","http://localhost:7080/javascript_alerts","http://localhost:7080/javascript_error","http://localhost:7080/key_presses","http://localhost:7080/large","http://localhost:7080/large_form","http://localhost:7080/multiple_dropdown","http://localhost:7080/windows","http://localhost:7080/nested_frames","http://localhost:7080/notification_message","http://localhost:7080/radio_buttons","http://localhost:7080/readonly","http://localhost:7080/redirector","http://localhost:7080/download_secure","http://localhost:7080/shadowdom","http://localhost:7080/shifting_content","http://localhost:7080/slow","http://localhost:7080/tables","http://localhost:7080/status_codes","http://localhost:7080/subdirectories","http://localhost:7080/two_factor","http://localhost:7080/typos","http://localhost:7080/tinymce","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/infinite_scroll/3","key":"http://localhost:7080/infinite_scroll/3","links":["http://localhost:7080/infinite_scroll/4"]},{"path":"/dynamic_controls","key":"http://localhost:7080/dynamic_controls","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/large_form","key":"http://localhost:7080/large_form","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/radio_buttons","key":"http://localhost:7080/radio_buttons","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/readonly","key":"http://localhost:7080/readonly","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/upload","key":"http://localhost:7080/upload","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]},{"path":"/login","key":"http://localhost:7080/login","links":["https://github.com/saucelabs/the-internet","http://elementalselenium.com/","https://saucelabs.com/"]}];
        // TFP-161: inbound links are counted among the pages that were loaded; the start page (/) needs none.
        const startPath = '/';
        const notLoaded: string[] = [];
        const inboundMap = new Map<string, number>();

        for (const page of pages) {
            inboundMap.set(page.key, 0);
        }

        for (const page of pages) {
            for (const linked of page.links) {
                // From another page: a page's links to itself (#top, #details) are not inbound links.
                if (linked !== page.key && inboundMap.has(linked)) {
                    inboundMap.set(linked, (inboundMap.get(linked) ?? 0) + 1);
                }
            }
        }

        for (const page of pages) {
            if (page.path === startPath) continue;
            const inbound = inboundMap.get(page.key) ?? 0;
            if (inbound === 0 && notLoaded.length > 0) {
                test.info().annotations.push({ type: 'finding', description: page.path + ' has no link from another loaded page; ' + notLoaded.join(', ') + ' could not be loaded, so a link from there was not seen' });
                continue;
            }
            expect(inbound, page.path + ' is not linked from any other inspected page').toBeGreaterThan(0);
        }
    });

