test.describe('Usability Coverage', () => {

  test('TFUS-026: the same components look the same on every inspected page (recorded as findings)', { annotation: [{ type: 'page', description: '/' }, { type: 'gate', description: 'read-only' }] }, async ({ page }) => {
    // ISTQB: equivalence partitioning (one component on different pages is one partition).
    const pages = ['/', '/infinite_scroll/3', '/dynamic_controls', '/large_form', '/radio_buttons', '/readonly', '/upload', '/login'];
    const seen = new Map<string, Map<string, Map<string, number>>>();
    for (const path of pages) {
      await tfGoto(page, path);
      for (const sample of await tfComponentSamples(page)) {
        for (const [property, value] of Object.entries(sample.values)) {
          const byProperty = seen.get(sample.key + ' | ' + property) ?? new Map<string, Map<string, number>>();
          const counts = byProperty.get(path) ?? new Map<string, number>();
          counts.set(value, (counts.get(value) ?? 0) + 1);
          byProperty.set(path, counts);
          seen.set(sample.key + ' | ' + property, byProperty);
        }
      }
    }
    for (const [key, byPage] of seen) {
      if (byPage.size < 2) continue;
      const usual = new Map([...byPage].map(([path, counts]) => [path, [...counts.entries()].sort((a, b) => b[1] - a[1])[0][0]]));
      const tally = new Map<string, string[]>();
      for (const [path, value] of usual) tally.set(value, [...(tally.get(value) ?? []), path]);
      if (tally.size < 2) continue;
      const [component, property] = key.split(' | ');
      const ranked = [...tally.entries()].sort((a, b) => b[1].length - a[1].length);
      const described = ranked.map(([value, where]) => value + ' on ' + where.join(', ')).join('; ');
      test.info().annotations.push({ type: 'finding', description: component + ' differs across pages in ' + property + ': ' + described });
    }
  });
});

test.describe('Responsive Coverage', () => {
  test('TFRM-001: keeps the core journey visible across common viewport sizes', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    const viewports = [
      { name: 'mobile', width: 390, height: 844 },
      { name: 'tablet', width: 768, height: 1024 },
      { name: 'desktop', width: 1440, height: 900 },
    ];

    // TFP-159: reveal what a closed menu or a collapsed navbar hides. The control is an element with
    // aria-expanded whose aria-controls (or data-bs-target, data-target, href="#id") names a hidden ancestor of the
    // target; failing that, one just before it - nearest ancestor first. A hidden control is revealed first, up to 3 levels.
    const tfReveal = async (target: ReturnType<typeof page.locator>, how: 'keyboard' | 'click'): Promise<{ visible: boolean; reason: string }> => {
      if (await target.isVisible()) return { visible: true, reason: '' };
      const start = await target.elementHandle({ timeout: 2000 }).catch(() => null);
      if (!start) return { visible: false, reason: 'it is not on the page' };
      const chain: Array<NonNullable<Awaited<ReturnType<typeof start.asElement>>>> = [];
      let current = start;
      for (let level = 0; level < 3; level += 1) {
        const toggle = (await current.evaluateHandle((node) => {
          const element = node as Element;
          const shown = (e: Element) => { const s = getComputedStyle(e); const r = e.getBoundingClientRect(); return s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0; };
          const toggles = Array.from(document.querySelectorAll('[aria-expanded]'));
          // Nearest hidden ancestor first; at each, a control naming it, then one just before it.
          for (let up = element.parentElement; up && up !== document.body; up = up.parentElement) {
            if (shown(up)) continue;
            const id = up.id;
            const named = id ? toggles.find((t) => t !== element && ((t.getAttribute('aria-controls') ?? '').split(/\s+/).includes(id) || [t.getAttribute('data-bs-target'), t.getAttribute('data-target'), t.getAttribute('href')].includes('#' + id))) : undefined;
            if (named) return named;
            const before = up.previousElementSibling;
            if (before && before.hasAttribute('aria-expanded')) return before;
          }
          return null;
        })).asElement();
        if (!toggle) break;
        chain.unshift(toggle);
        if (await toggle.isVisible()) break;
        current = toggle;
      }
      if (chain.length === 0) return { visible: false, reason: 'no control was found that reveals it' };
      for (const toggle of chain) {
        if (how === 'keyboard') {
          await toggle.focus({ timeout: 2000 }).catch(() => {});
          await page.keyboard.press('Enter');
        } else {
          await toggle.click({ timeout: 2000 }).catch(() => {});
        }
      }
      await target.waitFor({ state: 'visible', timeout: 2000 }).catch(() => {});
      if (await target.isVisible()) return { visible: true, reason: '' };
      const nearest = chain[chain.length - 1];
      const menu = await nearest.evaluate((e) => (e.getAttribute('aria-label') || e.textContent || '').trim().replace(/\s+/g, ' ')) || 'unnamed';
      const opened = (await nearest.getAttribute('aria-expanded')) === 'true';
      return { visible: false, reason: opened ? "the '" + menu + "' menu opened, but it stays hidden" : "the '" + menu + "' menu didn't open" };
    };

    for (const viewport of viewports) {
      await page.setViewportSize({ width: viewport.width, height: viewport.height });
      await tfGoto(page, '/');
      await page.waitForLoadState('domcontentloaded');
      await expect(page.locator('body')).toBeVisible();
      await expect(page.getByRole('heading').first()).toBeVisible();
      {
        const item = page.getByText('A/B Testing', { exact: true }).first();
        const reach = await tfReveal(item, 'click');
        await expect(item, 'A/B Testing should stay visible at ' + viewport.name + ' viewport' + (reach.reason ? ': ' + reach.reason : '')).toBeVisible();
      }
      {
        const item = page.getByText('Add/Remove Elements', { exact: true }).first();
        const reach = await tfReveal(item, 'click');
        await expect(item, 'Add/Remove Elements should stay visible at ' + viewport.name + ' viewport' + (reach.reason ? ': ' + reach.reason : '')).toBeVisible();
      }
      {
        const item = page.getByText('Basic Auth', { exact: true }).first();
        const reach = await tfReveal(item, 'click');
        await expect(item, 'Basic Auth should stay visible at ' + viewport.name + ' viewport' + (reach.reason ? ': ' + reach.reason : '')).toBeVisible();
      }
      {
        const item = page.getByText('Broken Images', { exact: true }).first();
        const reach = await tfReveal(item, 'click');
        await expect(item, 'Broken Images should stay visible at ' + viewport.name + ' viewport' + (reach.reason ? ': ' + reach.reason : '')).toBeVisible();
      }
      {
        const item = page.getByText('Canvas', { exact: true }).first();
        const reach = await tfReveal(item, 'click');
        await expect(item, 'Canvas should stay visible at ' + viewport.name + ' viewport' + (reach.reason ? ': ' + reach.reason : '')).toBeVisible();
      }
    }
  });

  test('TFRM-002: responds to a touch tap at mobile viewport', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await tfGoto(page, '/');
    await page.waitForLoadState('domcontentloaded');

    // Static introspection can't see touch-specific JS handlers, so this is
    // a smoke check that A/B Testing accepts a tap without erroring - not a
    // claim about what it does in response.
    const locator = page.getByText('A/B Testing', { exact: true }).first();
    await locator.scrollIntoViewIfNeeded();
    await locator.dispatchEvent('touchstart');
    await locator.dispatchEvent('touchend');
    await expect(page.locator('body')).toBeVisible();
  });
});

