test.describe('Performance Coverage', () => {
  test('TFPL-001: landing page finishes loading within 5 s', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    const response = await tfGoto(page, '/', { waitUntil: 'load' });
    expect(response, 'no response for /').not.toBeNull();
    expect(response!.status(), '/ answered with HTTP ' + response!.status()).toBeLessThan(400);

    await page.waitForFunction(() => {
      const entry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined;
      return !!entry && entry.loadEventEnd > 0;
    });
    const navigation = await page.evaluate(() => {
      const entry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
      return { total: entry.duration, firstByte: entry.responseStart, domReady: entry.domContentLoadedEventEnd };
    });

    expect(
      navigation.total,
      'navigation ' + Math.round(navigation.total) + ' ms, budget 5000 ms: the page took too long to load' +
        ' (first byte after ' + Math.round(navigation.firstByte) + ' ms, DOM ready after ' + Math.round(navigation.domReady) + ' ms). Measured once, in a lab (this run, from this machine), not from real visits.'
    ).toBeLessThan(5000);
  });

  test('TFPL-002: largest contentful paint stays under 4 s', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    await tfGoto(page, '/', { waitUntil: 'load' });

    // The browser's own largest-contentful-paint entries; the last one is the final LCP.
    const lcp = await page.evaluate(() => new Promise<{ time: number; element: string } | null>((resolve) => {
      let latest: { startTime: number; element?: Element | null; url?: string } | null = null;
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        latest = entries[entries.length - 1] as unknown as { startTime: number; element?: Element | null; url?: string };
      });
      observer.observe({ type: 'largest-contentful-paint', buffered: true });
      setTimeout(() => {
        observer.disconnect();
        if (!latest) return resolve(null);
        const el = latest.element;
        const text = el && el.textContent ? ' "' + el.textContent.trim().slice(0, 60) + '"' : '';
        const name = el ? el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + text : '';
        resolve({ time: latest.startTime, element: name || latest.url || 'unknown element' });
      }, 1000);
    }));

    if (!lcp) {
      // No contentful paint at all (e.g. an empty or canvas-only page): nothing to judge.
      test.info().annotations.push({ type: 'finding', description: 'the browser reported no largest contentful paint for /. Measured once, in a lab (this run, from this machine), not from real visits.' });
      return;
    }
    // Core Web Vitals bands (web.dev, checked 2026-10-05): up to 2.5 s good, up to 4 s needs improvement, beyond that poor.
    if (lcp.time > 2500 && lcp.time <= 4000) {
      test.info().annotations.push({ type: 'finding', description: 'LCP ' + (lcp.time / 1000).toFixed(2) + ' s on /: Core Web Vitals "needs improvement" (over 2.5 s, up to 4.0 s). Largest element: ' + lcp.element + '. Measured once, in a lab (this run, from this machine), not from real visits.' });
    }
    expect(
      lcp.time,
      'LCP ' + (lcp.time / 1000).toFixed(2) + ' s, budget 4.0 s: Core Web Vitals "poor". Largest element: ' + lcp.element + '. Measured once, in a lab (this run, from this machine), not from real visits.'
    ).toBeLessThanOrEqual(4000);
  });

  test('TFPL-003: page weight stays under 5 MB', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    // Sizes as the browser received them, for every request - cross-origin
    // ones included, which the Resource Timing API would report as 0 bytes.
    const sizes: Array<Promise<{ url: string; bytes: number }>> = [];
    page.on('requestfinished', (request) => {
      sizes.push(request.sizes().then((s) => ({ url: request.url(), bytes: s.responseBodySize + s.responseHeadersSize })).catch(() => ({ url: request.url(), bytes: 0 })));
    });
    await tfGoto(page, '/', { waitUntil: 'load' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    const resources = await Promise.all(sizes);
    const total = resources.reduce((sum, r) => sum + r.bytes, 0);
    const largest = [...resources]
      .sort((a, b) => b.bytes - a.bytes)
      .slice(0, 5)
      .map((r) => Math.round(r.bytes / 1024) + ' KB ' + r.url)
      .join('; ');
    expect(
      total,
      'page weight ' + (total / 1048576).toFixed(1) + ' MB over ' + resources.length + ' requests, budget 5 MB: clearly bloated. Largest: ' + largest + '. Measured once, in a lab (this run, from this machine), not from real visits.'
    ).toBeLessThan(5242880);
  });

  test('TFPL-004: no same-origin request fails while the page loads', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, baseURL }) => {
    const origin = new URL(baseURL ?? '/', 'http://placeholder.invalid').origin;
    const failures: string[] = [];
    page.on('response', (response) => {
      if (new URL(response.url()).origin === origin && response.status() >= 400) {
        failures.push('HTTP ' + response.status() + ' ' + response.url());
      }
    });
    page.on('requestfailed', (request) => {
      const reason = request.failure()?.errorText ?? 'failed';
      // An aborted request was cancelled by the page itself (navigation, a
      // superseded fetch), not refused by the server.
      if (new URL(request.url()).origin === origin && !/ERR_ABORTED/.test(reason)) {
        failures.push(reason + ' ' + request.url());
      }
    });
    await tfGoto(page, '/', { waitUntil: 'load' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    expect(failures, 'same-origin requests failed while / loaded: ' + failures.join('; ') + '. Measured once, in a lab (this run, from this machine), not from real visits.').toEqual([]);
  });

  test('TFPL-005: cumulative layout shift during load stays under 0.25', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    await tfGoto(page, '/', { waitUntil: 'load' });

    const cls = await page.evaluate(() => new Promise<{ value: number; sources: string }>((resolve) => {
      const shifts: Array<{ value: number; time: number; sources: string }> = [];
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries() as unknown as Array<{ value: number; startTime: number; hadRecentInput: boolean; sources?: Array<{ node?: Node | null }> }>) {
          if (entry.hadRecentInput) continue;
          const sources = (entry.sources ?? []).map((source) => {
            const node = source.node as Element | null | undefined;
            return node && node.tagName ? node.tagName.toLowerCase() + (node.id ? '#' + node.id : '') : 'unknown';
          }).slice(0, 3).join(', ');
          shifts.push({ value: entry.value, time: entry.startTime, sources });
        }
      });
      observer.observe({ type: 'layout-shift', buffered: true });
      setTimeout(() => {
        observer.disconnect();
        let best = { value: 0, sources: '' };
        let current = { value: 0, sources: '', start: -Infinity, last: -Infinity };
        for (const shift of shifts.sort((a, b) => a.time - b.time)) {
          if (shift.time - current.last > 1000 || shift.time - current.start > 5000) current = { value: 0, sources: '', start: shift.time, last: shift.time };
          current.value += shift.value;
          current.last = shift.time;
          current.sources = current.sources || shift.sources;
          if (current.value > best.value) best = { value: current.value, sources: current.sources };
        }
        resolve(best);
      }, 1500);
    }));

    const where = cls.sources ? ' Shifted first: ' + cls.sources + '.' : '';
    // Core Web Vitals bands (web.dev, checked 2026-10-05): up to 0.1 good, up to 0.25 needs improvement, beyond that poor.
    if (cls.value > 0.1 && cls.value <= 0.25) {
      test.info().annotations.push({ type: 'finding', description: 'CLS ' + cls.value.toFixed(3) + ' on /: Core Web Vitals "needs improvement" (over 0.1, up to 0.25).' + where + ' Measured once, in a lab (this run, from this machine), not from real visits.' });
    }
    expect(
      cls.value,
      'CLS ' + cls.value.toFixed(3) + ' on /, budget 0.25: Core Web Vitals "poor": content moves while the page loads.' + where + ' Measured once, in a lab (this run, from this machine), not from real visits.'
    ).toBeLessThanOrEqual(0.25);
  });

  test('TFPL-006: total blocking time during load (recorded, not judged)', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    await page.addInitScript(() => {
      const tasks: Array<{ start: number; duration: number }> = [];
      (window as unknown as { __tfLongTasks: typeof tasks }).__tfLongTasks = tasks;
      new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) tasks.push({ start: entry.startTime, duration: entry.duration });
      }).observe({ type: 'longtask' });
    });
    await tfGoto(page, '/', { waitUntil: 'load' });
    await page.waitForTimeout(1500);

    const tbt = await page.evaluate(() => {
      const tasks = (window as unknown as { __tfLongTasks?: Array<{ start: number; duration: number }> }).__tfLongTasks ?? [];
      const fcp = performance.getEntriesByName('first-contentful-paint')[0]?.startTime ?? 0;
      const blocking = tasks.filter((task) => task.start >= fcp).map((task) => Math.max(0, task.duration - 50));
      return { total: blocking.reduce((sum, ms) => sum + ms, 0), tasks: blocking.length };
    });
    test.info().annotations.push({ type: 'measurement', description: 'TBT ' + Math.round(tbt.total) + ' ms on / (' + tbt.tasks + ' long task(s) after the first contentful paint, up to 1.5 s after load): recorded, not judged - web.dev calls TBT a proxy for INP, not a substitute, and gives it no band. Measured once, in a lab (this run, from this machine), not from real visits.' });
  });
});

// This target is not HTTPS by default, so deeper transport-security validation should be handled outside this browser suite.
// Security: the passive checks are the Comprehensive run's own, on every inspected page, plus one request to a page that cannot exist. Missing or weak headers, cookie flags and software versions are findings and do not fail a test; a password exposed to plain HTTP or in a URL, an error page showing a stack trace or a server path, and an executed script payload do.
