  test.describe('Security Coverage', () => {
    test('TFSC-001: / sends its security headers and session cookies', { annotation: [{ type: 'page', description: '/' }, { type: 'gate', description: 'read-only' }, { type: 'category', description: 'A02:2025 Security Misconfiguration' }, { type: 'asvs', description: '3.4.1' }, { type: 'asvs', description: '3.4.3' }, { type: 'asvs', description: '3.4.4' }, { type: 'asvs', description: '3.4.5' }, { type: 'asvs', description: '3.4.6' }, { type: 'asvs', description: '3.3.1' }, { type: 'asvs', description: '3.3.3' }, { type: 'asvs', description: '3.3.4' }] }, async ({ tfShared }) => {
      const { page, context, response } = await tfShared.visit('/');
      expect(response, 'no response for /').not.toBeNull();
      const notAPage = tfNotAPage(response!.status());
      test.skip(notAPage !== null, '/ ' + notAPage);
      const headers = response!.headers();
      const https = new URL(page.url()).protocol === 'https:';
      const found: string[] = [];
      const csp = headers['content-security-policy'] ?? '';
      if (!csp) {
        found.push('no Content-Security-Policy header on /');
      } else {
        if (!/object-src\s+'none'/.test(csp)) found.push("the Content-Security-Policy on / lacks object-src 'none'");
        if (!/base-uri\s+'none'/.test(csp)) found.push("the Content-Security-Policy on / lacks base-uri 'none'");
      }
      if (!/frame-ancestors/.test(csp)) {
        found.push(headers['x-frame-options'] ? '/ relies on the obsolete X-Frame-Options; its Content-Security-Policy has no frame-ancestors' : 'any site can frame /: no Content-Security-Policy frame-ancestors (or X-Frame-Options)');
      }
      if ((headers['x-content-type-options'] ?? '').toLowerCase() !== 'nosniff') found.push('no X-Content-Type-Options: nosniff on /');
      const metaReferrer = page.locator('meta[name="referrer"]');
      const referrer = (headers['referrer-policy'] ?? ((await metaReferrer.count()) > 0 ? await metaReferrer.first().getAttribute('content') : null) ?? '').toLowerCase();
      if (!referrer) found.push('no referrer policy on / (no Referrer-Policy header or meta referrer)');
      else if (/unsafe-url|no-referrer-when-downgrade/.test(referrer)) found.push('the referrer policy on / (' + referrer + ') sends full URLs to other sites');
      if (https) {
        const hsts = headers['strict-transport-security'] ?? '';
        const maxAge = Number((/max-age=(\d+)/i.exec(hsts) ?? [])[1] ?? 0);
        if (!hsts) found.push('no Strict-Transport-Security header on /');
        else if (maxAge < 31536000) found.push('Strict-Transport-Security on / lasts ' + maxAge + ' seconds, under a year');
      }
      const host = new URL(page.url()).hostname;
      for (const cookie of await context.cookies()) {
        const domain = cookie.domain.replace(/^\./, '');
        if (!(host === domain || host.endsWith('.' + domain)) || !/(^|[._-])(session|sess|sid|auth|token|jwt)([._-]|$)|^(jsessionid|phpsessid|asp\.net_sessionid|connect\.sid|rack\.session|laravel_session)$/i.test(cookie.name)) continue;
        const named = 'session cookie "' + cookie.name + '" set on /';
        if (https && !cookie.secure) found.push(named + ' has no Secure attribute');
        if (!cookie.httpOnly) found.push(named + ' has no HttpOnly attribute, so page scripts can read it');
        if (domain !== host) found.push(named + ' is set for ' + cookie.domain + ', so every subdomain of ' + domain + ' receives it');
        const days = cookie.expires > 0 ? (cookie.expires * 1000 - Date.now()) / 86400000 : 0;
        if (days > 30) found.push(named + ' stays valid for ' + Math.round(days) + ' days, more than 30 (A07:2025 Authentication Failures, CWE-613)');
      }
      for (const description of found) test.info().annotations.push({ type: 'finding', description });
    });

    test('TFSC-002: / names no software version in its response headers', { annotation: [{ type: 'page', description: '/' }, { type: 'gate', description: 'read-only' }, { type: 'category', description: 'A01:2025 Broken Access Control' }, { type: 'asvs', description: '13.4.6' }] }, async ({ tfShared }) => {
      const { page, response } = await tfShared.visit('/');
      expect(response, 'no response for /').not.toBeNull();
      const headers = response!.headers();
      for (const name of ['server', 'x-powered-by', 'x-aspnet-version', 'x-aspnetmvc-version']) {
        const value = headers[name];
        if (value && /\d/.test(value)) test.info().annotations.push({ type: 'finding', description: name + ': ' + value + ' on / names a software version' });
      }
    });

    test('TFSC-003: / keeps passwords off plain HTTP', { annotation: [{ type: 'page', description: '/' }, { type: 'gate', description: 'read-only' }, { type: 'category', description: 'A04:2025 Cryptographic Failures' }, { type: 'asvs', description: '12.2.1' }] }, async ({ tfShared }) => {
      const { page, response } = await tfShared.visit('/');
      const notAPage = response ? tfNotAPage(response.status()) : null;
      test.skip(notAPage !== null, '/ ' + notAPage);
      const problems: string[] = [];
      const secure = await page.evaluate(() => window.isSecureContext);
      const fields = await page.locator('input[type="password"]').evaluateAll((elements) => elements.map((element) => (element as HTMLInputElement).name || element.id || 'unnamed'));
      if (!secure && fields.length > 0) problems.push('/ is served over plain HTTP and has a password field (' + fields.join(', ') + ')');
      if (secure) {
        const targets = await page.locator('form').evaluateAll((forms) => forms.filter((form) => form.querySelector('input[type="password"]')).map((form) => new URL(form.getAttribute('action') || location.href, location.href).href));
        for (const target of targets) {
          const url = new URL(target);
          if (url.protocol === 'http:' && !tfIsLocalHost(url.hostname)) problems.push('a form on / sends a password field to the plain-HTTP address ' + target);
        }
      }
      if (new URL(page.url()).protocol === 'https:') {
        const insecure = await page.evaluate(() => Array.from(document.querySelectorAll('img[src], script[src], iframe[src], audio[src], video[src], source[src], embed[src], link[rel~="stylesheet"][href], object[data]'))
          .map((element) => element.getAttribute('src') ?? element.getAttribute('href') ?? element.getAttribute('data') ?? '')
          .map((value) => { try { return new URL(value, location.href); } catch { return null; } })
          .filter((url): url is URL => url !== null && url.protocol === 'http:')
          .map((url) => url.href));
        for (const url of new Set(insecure)) test.info().annotations.push({ type: 'finding', description: '/ is served over HTTPS but loads ' + url + ' over plain HTTP (mixed content)' });
      }
      expect(problems, 'passwords exposed to plain HTTP: ' + problems.join('; ')).toEqual([]);
    });

    test('TFSC-004: / puts no password or session token in a URL', { annotation: [{ type: 'page', description: '/' }, { type: 'gate', description: 'read-only' }, { type: 'category', description: 'A06:2025 Insecure Design' }, { type: 'asvs', description: '14.2.1' }] }, async ({ tfShared }) => {
      const { page, response } = await tfShared.visit('/');
      const notAPage = response ? tfNotAPage(response.status()) : null;
      test.skip(notAPage !== null, '/ ' + notAPage);
      const problems: string[] = [];
      const chain: string[] = [];
      for (let request = response?.request() ?? null; request; request = request.redirectedFrom()) chain.push(request.url());
      for (const url of chain) {
        const names = tfSensitiveParams(url);
        if (names.length > 0) problems.push('loading / went through ' + url + ', which carries ' + names.join(', ') + ' in the URL');
      }
      const links = await page.locator('a[href]').evaluateAll((anchors) => anchors.map((anchor) => (anchor as HTMLAnchorElement).href));
      for (const href of new Set(links)) {
        const names = tfSensitiveParams(href);
        if (names.length > 0) problems.push('a link on / to ' + href + ' carries ' + names.join(', ') + ' in its URL');
      }
      const getForms = await page.locator('form').evaluateAll((forms) => forms
        .filter((form) => (form.getAttribute('method') || 'get').toLowerCase() === 'get' && form.querySelector('input[type="password"]'))
        .map((form) => new URL(form.getAttribute('action') || location.href, location.href).href));
      for (const target of getForms) problems.push('a form on / would send its password field in the URL (method GET, to ' + target + ')');
      expect(problems, 'secrets in URLs: ' + problems.join('; ')).toEqual([]);
    });
  });

  test.describe('Functional Coverage', () => {
    test('TFFU-056: hover state: links show pointer cursor and preserve tooltip attributes', { annotation: { type: 'gate', description: 'read-only' } }, async ({ tfShared }) => {
          await tfShared.rerun(async () => {
            const { page } = await tfShared.visit('/');
            tfShared.changed();
            await page.waitForLoadState('domcontentloaded');

            const visibleLinks = page.locator('a[href]:visible');
            const count = await visibleLinks.count();
            // TFP-142: each hover gets 2 s and the check 15 s. A link that can't
            // be hovered - a skip link parked off-screen, one under an overlay -
            // made hover() retry until the 30 s test timeout (rizonetech.com,
            // 5 of 5 pages). It is now named as not checked, with the reason.
            const deadline = Date.now() + 15000;
            const notHovered: string[] = [];

            for (let index = 0; index < count; index += 1) {
                const locator = visibleLinks.nth(index);
                if (Date.now() > deadline) {
                    test.info().annotations.push({ type: 'finding', description: (count - index) + ' of ' + count + ' links not hovered: the check stops after 15 s' });
                    break;
                }
                const hovered = await locator.hover({ timeout: 2000 }).then(() => null, (error: Error) => (error.message.match(/outside of the viewport|intercepts pointer events|not stable|not visible/) ?? ['did not respond within 2 s'])[0]);
                if (hovered !== null) {
                    notHovered.push((await locator.getAttribute('href')) + ' (' + hovered + ')');
                    continue;
                }
                const { cursor, title } = await locator.evaluate((node) => ({ cursor: window.getComputedStyle(node).cursor, title: node.getAttribute('title') }));
                expect(cursor).toBe('pointer');

                if (title) {
                    expect(title.trim().length).toBeGreaterThan(0);
                }
            }
            if (notHovered.length > 0) {
                test.info().annotations.push({ type: 'finding', description: 'links that could not be hovered, so their cursor was not checked: ' + notHovered.join(', ') });
            }
          });
      });

    test('TFFU-182: link "Infinite Scroll" on /: on the page, named, with a valid href', { annotation: [{ type: 'gate', description: 'read-only' }, { type: 'page', description: '/' }] }, async ({ tfShared }) => {
      await tfShared.rerun(async () => {
        const { page } = await tfShared.visit('/');
        tfShared.changed();
        // By the generator's own locator, or by its own address when the page names it otherwise.
        const link = page.getByRole('link', { name: 'Infinite Scroll', exact: true }).first().or(page.locator('a[href="/infinite_scroll"]').first()).first();
        await expect(link, '"Infinite Scroll" is on /').toBeAttached();
        // The link, or what renders it: an anchor around a positioned image has no box of its own.
        await expect(link.or(link.locator('*')).filter({ visible: true }).first(), '"Infinite Scroll" is visible on /').toBeVisible();
        await expect(link, '"Infinite Scroll" has a name').toHaveAccessibleName(/\S/);
        const href = (await link.getAttribute('href')) ?? '';
        expect(href.trim(), '"Infinite Scroll" has an href').not.toBe('');
        expect(() => new URL(href, page.url()), '"Infinite Scroll" has a valid href: ' + href).not.toThrow();
        // Its target: loaded by the link-health check.
      });
    });
  });

