          found.push(headers['x-frame-options'] ? '/infinite_scroll/3 relies on the obsolete X-Frame-Options; its Content-Security-Policy has no frame-ancestors' : 'any site can frame /infinite_scroll/3: no Content-Security-Policy frame-ancestors (or X-Frame-Options)');
