        if (!referrer) found.push('no referrer policy on /infinite_scroll/3 (no Referrer-Policy header or meta referrer)');
        else if (/unsafe-url|no-referrer-when-downgrade/.test(referrer)) found.push('the referrer policy on /infinite_scroll/3 (' + referrer + ') sends full URLs to other sites');
