        found.push(headers['x-frame-options'] ? '/dynamic_controls relies on the obsolete X-Frame-Options; its Content-Security-Policy has no frame-ancestors' : 'any site can frame /dynamic_controls: no Content-Security-Policy frame-ancestors (or X-Frame-Options)');
