          const links = [{"text":"","url":"https://github.com/saucelabs/the-internet","rawHref":"https://github.com/saucelabs/the-internet","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":false,"target":"","targetBehavior":"same-window","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Elemental Selenium","url":"http://elementalselenium.com/","rawHref":"http://elementalselenium.com/","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":false},{"text":"Sauce Labs","url":"https://saucelabs.com/","rawHref":"https://saucelabs.com/","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];
