      test.skip(read.lang !== '' && !/^en(-(us|gb))?$/i.test(read.lang), '/upload is in ' + read.lang + ': only English (en-US, en-GB) is checked');
      test.skip(read.pieces.length === 0, 'no interface text on /upload');
      const speller = await tfSpeller();
      const reported = new Set<string>();
      for (const piece of read.pieces) {
        for (const word of tfWordsOf(piece.text)) {
          if (reported.has(word) || speller.known(word)) continue;
          const suggestions = speller.suggest(word);
          if (suggestions.length === 0) continue;
          reported.add(word);
          test.info().annotations.push({ type: 'finding', description: '"' + word + '" in ' + piece.where + ' on /upload is not in the dictionary (en-US, en-GB); did you mean ' + suggestions.map((suggestion) => '"' + suggestion + '"').join(' or ') + '?' });
        }
      }
      for (const field of read.fields) {
        const labelWords = tfWordsOf(field.label);
        for (const word of tfWordsOf(field.placeholder)) {
          const near = labelWords.find((labelWord) => labelWord.toLowerCase() !== word.toLowerCase() && labelWord[0].toLowerCase() === word[0].toLowerCase() && speller.distance(word, labelWord) <= 2);
          if (!near || labelWords.some((labelWord) => labelWord.toLowerCase() === word.toLowerCase()) || reported.has(word)) continue;
          reported.add(word);
          test.info().annotations.push({ type: 'finding', description: '"' + word + '" in the placeholder "' + field.placeholder + '" on /upload looks like a misspelling of its label\'s "' + near + '"' });
        }
      }
